local SoundService = game:GetService("\083\111\117\110\100\083\101\114\118\105\099\101")
local Debris = game:GetService("\068\101\098\114\105\115")
local function playMenuSound(assetId, volume)
    local sound = Instance.new("\083\111\117\110\100")
    sound.Name = "\121\048\117\110\103\068\097\114\101\085\073\083\111\117\110\100"
    sound.SoundId = "\114\098\120\097\115\115\101\116\105\100\058\047\047" .. tostring(assetId)
    sound.Volume = volume or 0.7
    sound.Parent = SoundService
    sound:Play()
    Debris:AddItem(sound, 0x8)
end

local connectedSoundButtons = {}
local function attachButtonSounds(object)
    if not object:IsA("\071\117\105\066\117\116\116\111\110") or connectedSoundButtons[object] then return end
    connectedSoundButtons[object] = true
    object.MouseEnter:Connect(function()
        if object.Visible and object.Active then
            playMenuSound(0x567c0a4790f6, 0.6)
        end
    end)
    object.Activated:Connect(function()
        playMenuSound(0x4be7ab04423b, 0.75)
    end)
end

_01IIOOOIO1Il0IOOIo100I01_0.DescendantAdded:Connect(attachButtonSounds)
 


