local function addWifiArc(name, radius, thickness)
    local centerX, centerY = 0x1b, 0x2a
    local segments = 0x19
    for i = 0x0, segments - 0x1 do
         
        local angle = math.rad(0x1e + (0x78 * i / (segments - 0x1)))
        local x = centerX + radius * math.cos(angle)
        local y = centerY - radius * math.sin(angle)
        local segment = Instance.new("\070\114\097\109\101")
        segment.Name = name .. tostring(i + 0x1)
        segment.AnchorPoint = Vector2.new(0.5, 0.5)
        segment.Position = UDim2.fromOffset(x, y)
        segment.Size = UDim2.fromOffset(thickness + 0x1, thickness + 0x1)
        segment.BackgroundColor3 = Color3.fromRGB(0xff, 0x37, 0x37)
        segment.BorderSizePixel = 0x0
        segment.ZIndex = 0x15
        segment.Parent = _ool0o1oO0O1O010lO1OIoIl1_35
        local round = Instance.new("\085\073\067\111\114\110\101\114")
        round.CornerRadius = UDim.new(0x1, 0x0)
        round.Parent = segment
        table.insert(wifiParts, segment)
    end
end
