            if treeModel then table.insert(ignore, treeModel) end
            if secondTreeModel then table.insert(ignore, secondTreeModel) end
            params.IgnoreWater = true
            local floorY = nil
            local originY = (referenceY or 98.00) + 1.5
            for _ = 0x1, 0x23 do
                params.FilterDescendantsInstances = ignore
                local hit = Workspace:Raycast(Vector3.new(x, originY, z), Vector3.new(0x0, -0xa0, 0x0), params)
                if not hit then break end
                local surface = hit.Instance
                local isGround = hit.Normal.Y > 0.65 and (
                    surface:IsA('\084\101\114\114\097\105\110') or
                    (surface:IsA('\066\097\115\101\080\097\114\116') and surface.CanCollide and surface.Transparency < 0.9)
                )
                if isGround then
                    floorY = hit.Position.Y
                    break
                end
                table.insert(ignore, surface)
            end
             
            local base = Vector3.new(x, floorY or ((referenceY or 98.00) - 0x3), z)
             
             
            local trunk = part('\084\114\101\101\084\114\117\110\107', Vector3.new(5.2, 1.8, 1.8), CFrame.new(base + Vector3.new(0x0, 2.6, 0x0)) * CFrame.Angles(0x0, 0x0, math.rad(0x5a)), Color3.fromRGB(0x50, 0x31, 0x1e), Enum.Material.Wood, currentTreeModel)
            trunk.Shape = Enum.PartType.Cylinder
            local greenColors = {
