                Color3.fromRGB(0x12, 0x43, 0x1f),
                Color3.fromRGB(0xc, 0x30, 0x19),
            }
             
            local levels = 0x8
            for level = 0x1, levels do
                local height = 5.1 + (level - 0x1) * 1.45
                local radius = 5.0 - (level - 0x1) * 0.52
                local count = 0xc
                for j = 0x1, count do
                    local angle = (j / count) * math.pi * 0x2 + (level % 0x2) * 0.18
