                local core = part('\080\105\110\101\067\101\110\116\101\114', Vector3.new(radius * 1.35, 2.7, radius * 1.35), CFrame.new(base + Vector3.new(0x0, height, 0x0)), greenColors[level % #greenColors + 0x1], Enum.Material.Grass, currentTreeModel)
                core.Shape = Enum.PartType.Ball
