        local wallDecorModel
        local function makeWallDecorations(currentGeneration)
            if wallDecorModel then wallDecorModel:Destroy() end
            wallDecorModel = Instance.new('\077\111\100\101\108')
            wallDecorModel.Name = '\076\111\099\097\108\067\104\114\105\115\116\109\097\115\087\097\108\108\068\101\099\111\114\097\116\105\111\110\115'
            wallDecorModel.Parent = Workspace
            local root = wallDecorModel
            local red = Color3.fromRGB(0xcd, 0x20, 0x2e)
            local gold = Color3.fromRGB(0xf4, 0xc2, 0x39)
            local greens = {Color3.fromRGB(0x11, 0x5a, 0x26), Color3.fromRGB(0x19, 0x71, 0x30), Color3.fromRGB(0xc, 0x48, 0x20)}
            local function decorPart(name, size, cf, color, shape, material)
                local p = Instance.new('\080\097\114\116')
                p.Name = name
                p.Size = size
                p.CFrame = cf
                p.Color = color
                p.Material = material or Enum.Material.SmoothPlastic
                if shape then p.Shape = shape end
                p.Anchored = true
                p.CanCollide = false
                p.CanTouch = false
                p.CanQuery = false
                p.CastShadow = false
                p.Parent = root
                return p
            end
            local function wreath(faceCF, radius)
                 
                local count = 0xe
                for i = 0x1, count do
                    local a = (i - 0x1) * math.pi * 0x2 / count
                    local pos = Vector3.new(math.cos(a) * radius, math.sin(a) * radius, 0x0)
                    decorPart('\087\114\101\097\116\104\069\118\101\114\103\114\101\101\110', Vector3.new(0.58, 0.58, 0.58), faceCF * CFrame.new(pos), greens[i % #greens + 0x1], Enum.PartType.Ball)
                end
                for _, i in ipairs({0x2, 0x6, 0xa}) do
                    local a = (i - 0x1) * math.pi * 0x2 / count
                    decorPart('\087\114\101\097\116\104\066\101\114\114\121', Vector3.new(0.23, 0.23, 0.23), faceCF * CFrame.new(math.cos(a)*radius, math.sin(a)*radius, 0.37), red, Enum.PartType.Ball, Enum.Material.Neon)
                end
                decorPart('\087\114\101\097\116\104\066\111\119\067\101\110\116\101\114', Vector3.new(0.40, 0.36, 0.18), faceCF * CFrame.new(0x0, -radius - 0.08, 0.38), red, Enum.PartType.Ball)
                for _, sign in ipairs({-0x1, 0x1}) do
                    decorPart('\087\114\101\097\116\104\066\111\119\076\111\111\112', Vector3.new(0.52, 0.33, 0.18), faceCF * CFrame.new(sign*0.39, -radius + 0.05, 0.38) * CFrame.Angles(0x0, 0x0, sign*0.35), red, Enum.PartType.Ball)
                end
            end
            local function garland(faceCF, halfWidth, topY, seed)
                local length = math.min(halfWidth * 0x2 - 1.2, 0x1c)
                if length < 0x5 then return end
                local steps = math.max(0x8, math.floor(length / 0.8))
                for i = 0x0, steps do
                    local t = i / steps
                    local x = (t - 0.5) * length
                    local sag = math.sin(t * math.pi) * 0.85
                    local cf = faceCF * CFrame.new(x, topY - sag, 0x0)
                    decorPart('\069\118\101\114\103\114\101\101\110\087\097\108\108\071\097\114\108\097\110\100', Vector3.new(0.68, 0.68, 0.68), cf, greens[(i + seed) % #greens + 0x1], Enum.PartType.Ball)
                    if i % 0x3 == 0x0 then
                        local color = (i + seed) % 0x2 == 0x0 and red or gold
                        decorPart('\071\097\114\108\097\110\100\079\114\110\097\109\101\110\116', Vector3.new(0.32, 0.32, 0.32), cf * CFrame.new(0x0, -0.40, 0.25), color, Enum.PartType.Ball, Enum.Material.Neon)
                    end
                end
            end
             
            local function bow(cf)
                decorPart('\067\104\114\105\115\116\109\097\115\066\111\119\075\110\111\116', Vector3.new(0.45,0.42,0.22), cf, red, Enum.PartType.Ball)
                for _, s in ipairs({-0x1,0x1}) do
                    decorPart('\067\104\114\105\115\116\109\097\115\066\111\119\076\111\111\112', Vector3.new(0.72,0.44,0.20), cf * CFrame.new(s*0.43,0.07,0x0) * CFrame.Angles(0x0,0x0,s*0.3), red, Enum.PartType.Ball)
                    decorPart('\067\104\114\105\115\116\109\097\115\066\111\119\082\105\098\098\111\110', Vector3.new(0.25,0.85,0.13), cf * CFrame.new(s*0.19,-0.53,0x0) * CFrame.Angles(0x0,0x0,s*0.2), red)
                end
            end
            local function ornament(cf, color, drop)
                decorPart('\072\097\110\103\105\110\103\079\114\110\097\109\101\110\116\083\116\114\105\110\103', Vector3.new(0.045,drop,0.045), cf * CFrame.new(0x0,-drop/0x2,0x0), gold)
                decorPart('\072\097\110\103\105\110\103\067\104\114\105\115\116\109\097\115\066\097\117\098\108\101', Vector3.new(0.55,0.65,0.55), cf * CFrame.new(0x0,-drop-0.32,0x0), color, Enum.PartType.Ball, Enum.Material.Neon)
                decorPart('\066\097\117\098\108\101\067\097\112', Vector3.new(0.18,0.13,0.18), cf * CFrame.new(0x0,-drop+0.04,0x0), gold)
            end
            local candidates = {}
            for _, obj in ipairs(Workspace:GetDescendants()) do
                if obj:IsA('\066\097\115\101\080\097\114\116') and obj.Anchored and obj.Transparency < 0.45
                    and obj.Size.Y >= 0x6 and obj.Size.Y <= 0x5a
                    and math.abs(obj.CFrame.UpVector.Y) > 0.9
                    and not obj:FindFirstAncestor('\076\111\099\097\108\067\104\114\105\115\116\109\097\115\084\114\101\101')
                    and not obj:FindFirstAncestor('\076\111\099\097\108\067\104\114\105\115\116\109\097\115\084\114\101\101\083\101\099\111\110\100')
                    and not obj:FindFirstAncestor('\076\111\099\097\108\067\104\114\105\115\116\109\097\115\084\114\101\101\084\104\105\114\100')
                    and not obj:FindFirstAncestor('\076\111\099\097\108\067\104\114\105\115\116\109\097\115\083\110\111\119\109\097\110')
                    and not obj:FindFirstAncestor('\076\111\099\097\108\067\104\114\105\115\116\109\097\115\067\097\109\112\102\105\114\101')
                    and not obj:FindFirstAncestor('\076\111\099\097\108\067\104\114\105\115\116\109\097\115\083\116\114\105\110\103\076\105\103\104\116\115')
                    and not obj:IsDescendantOf(root) then
                    local x, z = obj.Size.X, obj.Size.Z
                    local wide, thick = math.max(x,z), math.min(x,z)
                    local n = obj.Name:lower()
                    local excluded = n:find('\100\111\111\114') or n:find('\119\105\110\100\111\119') or n:find('\103\108\097\115\115')
                        or n:find('\102\101\110\099\101') or n:find('\103\097\116\101') or n:find('\098\097\114') or n:find('\112\105\108\108\097\114')
                    if not excluded and wide >= 0x7 and thick <= 0x5 and wide / math.max(thick,0.1) >= 2.6 then
                        table.insert(candidates, {part=obj, wide=wide})
                    end
                end
            end
            table.sort(candidates, function(a,b) return a.wide > b.wide end)
            local decorated = 0x0
            for _, entry in ipairs(candidates) do
                if not enabled or generation ~= currentGeneration or decorated >= 0xb4 then break end
                local wall = entry.part
                if wall.Parent then
                    local cf = wall.CFrame
                    local alongX = wall.Size.X >= wall.Size.Z
                    local half = entry.wide / 0x2
                    for _, side in ipairs({-0x1,0x1}) do
                        local faceCF
                        if alongX then
                            faceCF = cf * CFrame.new(0x0,0x0,side*(wall.Size.Z/0x2+0.55)) * CFrame.Angles(0x0,side == 0x1 and 0x0 or math.pi,0x0)
                        else
                            faceCF = cf * CFrame.new(side*(wall.Size.X/0x2+0.55),0x0,0x0) * CFrame.Angles(0x0,side*math.pi/0x2,0x0)
                        end
                        local topY = wall.Size.Y/0x2 - 0.95
                         
                        local sections = math.max(0x1, math.min(0x9, math.floor(entry.wide / 0x7)))
                        local sectionWidth = entry.wide / sections
                        for section = 0x1, sections do
                            local offset = -half + sectionWidth*(section-0.5)
                            local sectionCF = faceCF * CFrame.new(offset,0x0,0x0)
                            garland(sectionCF, sectionWidth/0x2, topY, decorated+section)
                            if wall.Size.Y >= 0x8 then
                                wreath(sectionCF * CFrame.new(0x0,math.min(0x1,wall.Size.Y*0.07),0x0), 1.05)
                            end
                            bow(sectionCF * CFrame.new(0x0,topY-0.4,0.35))
                            if sectionWidth >= 0x5 then
                                local palette = {red,gold,Color3.fromRGB(0x2d,0xa0,0xff),Color3.fromRGB(0x41,0xd2,0x5f)}
                                ornament(sectionCF * CFrame.new(-sectionWidth*0.26,topY-0.5,0.5),palette[(section+decorated)%0x4+0x1],0.65)
                                ornament(sectionCF * CFrame.new(sectionWidth*0.26,topY-0.5,0.5),palette[(section+decorated+0x2)%0x4+0x1],1.0)
                            end
                        end
                    end
                    decorated = decorated + 0x1
                end
                if decorated % 0x2 == 0x0 then task.wait() end
            end
        end
        
         
        local carpetModel
        local function makeRedCarpets(currentGeneration)
            if carpetModel then carpetModel:Destroy() end
            carpetModel = Instance.new('\077\111\100\101\108')
            carpetModel.Name = '\076\111\099\097\108\067\104\114\105\115\116\109\097\115\082\101\100\067\097\114\112\101\116\115'
            carpetModel.Parent = Workspace
            local created = 0x0
            local seen = {}
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            local ignore = {carpetModel}
            if player.Character then table.insert(ignore, player.Character) end
            if model then table.insert(ignore, model) end
            if treeModel then table.insert(ignore, treeModel) end
            if secondTreeModel then table.insert(ignore, secondTreeModel) end
            if thirdTreeModel then table.insert(ignore, thirdTreeModel) end
            if snowmanModel then table.insert(ignore, snowmanModel) end
            if stringLightsModel then table.insert(ignore, stringLightsModel) end
            if wallDecorModel then table.insert(ignore, wallDecorModel) end
            params.FilterDescendantsInstances = ignore
            params.IgnoreWater = true
            for index, floor in ipairs(Workspace:GetDescendants()) do
                if not enabled or generation ~= currentGeneration or created >= 0x87 then break end
                if index % 0x78 == 0x0 then task.wait() end
                if floor:IsA('\066\097\115\101\080\097\114\116') and floor.Anchored and floor.CanCollide and floor.Transparency < 0.45
                    and floor.Size.X >= 0x7 and floor.Size.Z >= 0x7 and floor.Size.Y <= 0x8
                    and floor.CFrame.UpVector.Y > 0.94
                    and not floor:FindFirstAncestor('\076\111\099\097\108\067\104\114\105\115\116\109\097\115\082\101\100\067\097\114\112\101\116\115')
                    and not floor:FindFirstAncestor('\076\111\099\097\108\067\104\114\105\115\116\109\097\115\087\097\108\108\068\101\099\111\114\097\116\105\111\110\115')
                    and not floor:FindFirstAncestor('\076\111\099\097\108\067\104\114\105\115\116\109\097\115\083\116\114\105\110\103\076\105\103\104\116\115') then
                    local name = floor.Name:lower()
                    local original = savedParts[floor]
                    local material = original and original.Material or floor.Material
                    local snow = floor.Material == Enum.Material.Snow
                        or material == Enum.Material.Snow or material == Enum.Material.Grass
                        or material == Enum.Material.Ground or material == Enum.Material.Sand
                        or material == Enum.Material.Slate or material == Enum.Material.Mud
                        or material == Enum.Material.LeafyGrass
                    local unsuitable = name:find('\114\111\111\102') or name:find('\099\101\105\108\105\110\103') or name:find('\119\097\108\108')
                        or name:find('\103\114\097\115\115') or name:find('\121\097\114\100') or name:find('\114\111\097\100')
                        or name:find('\098\097\115\101\112\108\097\116\101') or name:find('\116\101\114\114\097\105\110') or name:find('\115\110\111\119')
                    if not snow and not unsuitable then
                        local top = floor.Position + floor.CFrame.UpVector * (floor.Size.Y * 0.5)
                        params.FilterDescendantsInstances = ignore
                        local hit = Workspace:Raycast(top + Vector3.new(0x0, 0.6, 0x0), Vector3.new(0x0, 0x20, 0x0), params)
                         
                        if hit and hit.Instance ~= floor and hit.Position.Y > top.Y + 0x3 then
                            local key = math.floor(top.X / 0xc) .. '\058' .. math.floor(top.Z / 0xc) .. '\058' .. math.floor(top.Y / 0x8)
                            if not seen[key] then
                                seen[key] = true
                                local width = math.min(floor.Size.X - 0x1, 0x7)
                                local length = math.min(floor.Size.Z - 0x1, 0x18)
                                if width >= 0x3 and length >= 0x4 then
                                    local carpet = Instance.new('\080\097\114\116')
                                    carpet.Name = '\067\104\114\105\115\116\109\097\115\082\101\100\067\097\114\112\101\116'
                                    carpet.Anchored = true
                                    carpet.CanCollide = false
                                    carpet.CanTouch = false
                                    carpet.CanQuery = false
                                    carpet.CastShadow = false
                                    carpet.Material = Enum.Material.Fabric
                                    carpet.Color = Color3.fromRGB(0x9c, 0x12, 0x1f)
                                    carpet.Size = Vector3.new(width, 0.065, length)
                                    carpet.CFrame = floor.CFrame * CFrame.new(0x0, floor.Size.Y * 0.5 + 0.038, 0x0)
                                    carpet.Parent = carpetModel
                                     
                                    for side = -0x1, 0x1, 0x2 do
                                        local trim = Instance.new('\080\097\114\116')
                                        trim.Name = '\071\111\108\100\067\097\114\112\101\116\084\114\105\109'
                                        trim.Anchored = true
                                        trim.CanCollide = false
                                        trim.CanTouch = false
                                        trim.CanQuery = false
                                        trim.CastShadow = false
                                        trim.Material = Enum.Material.Fabric
                                        trim.Color = Color3.fromRGB(0xc5, 0x91, 0x37)
                                        trim.Size = Vector3.new(0.11, 0.012, length)
                                        trim.CFrame = carpet.CFrame * CFrame.new(side * (width / 0x2 - 0.15), 0.04, 0x0)
                                        trim.Parent = carpetModel
                                    end
                                    created = created + 0x1
                                end
                            end
                        end
                    end
                end
            end
        end
        
        local function start()
            if enabled then return end
            enabled = true
            generation = generation + 0x1
            local currentGeneration = generation
            setButton(true)  
