            for i,fixture in ipairs(partyFixtures) do
                local t=partyClock
                local index=(math.floor(t*0x2+fixture.phase)%#palette)+0x1
                local color=palette[index]
                if fixture.orb.Parent then fixture.orb.Color=color end
                if fixture.light.Parent then
                    fixture.light.Color=color
                    fixture.light.Brightness=1.4+math.abs(math.sin(t*3.5+fixture.phase))*0x3
                end
                if fixture.mount and fixture.mount.Parent then
                    fixture.mount.CFrame=CFrame.new(fixture.base+Vector3.new(0x0,2.5,0x0))
                        *CFrame.Angles(math.rad(0x41)+math.sin(t*.9+fixture.phase)*.6,t*.75+fixture.phase,0x0)
                    fixture.mount.Color=color
                    fixture.spot.Color=color
                    fixture.beam.Color=ColorSequence.new(color)
                end
            end
            for i,tile in ipairs(danceTiles) do
                if tile.Parent then
                    tile.Color=palette[(math.floor(partyClock*0x4+i*.7)%#palette)+0x1]
                    tile.Transparency=.18+.22*math.abs(math.sin(partyClock*0x2+i))
                end
