                if part.Parent then
                    local x,z=part.Position.X,part.Position.Z
                    minX=math.min(minX,x); maxX=math.max(maxX,x)
                    minZ=math.min(minZ,z); maxZ=math.max(maxZ,z)
                    minY=math.min(minY,part.Position.Y-part.Size.Y/0x2)
                    maxY=math.max(maxY,part.Position.Y+part.Size.Y/0x2)
                end
            end
            if minX==math.huge then
                minX,maxX,minZ,maxZ,minY,maxY=-0x12c,0x12c,-0x12c,0x12c,0x0,0x78
            end
            local centerX,centerZ=(minX+maxX)/0x2,(minZ+maxZ)/0x2
            local spanX=math.clamp(maxX-minX+0x50,0xfa,0x708)
            local spanZ=math.clamp(maxZ-minZ+0x50,0xfa,0x708)
            local columns=math.clamp(math.ceil(spanX/0x20),0xd,0x23)
            local rows=math.clamp(math.ceil(spanZ/0x20),0xd,0x23)
            local rayParams=RaycastParams.new()
            rayParams.FilterType=Enum.RaycastFilterType.Exclude
            rayParams.FilterDescendantsInstances={partyFolder,player.Character}
            rayParams.IgnoreWater=true
            for row=0x1,rows do
                for col=0x1,columns do
                    local i=(row-0x1)*columns+col
                    local x=centerX+((col-.5)/columns-.5)*spanX
                    local z=centerZ+((row-.5)/rows-.5)*spanZ
                    local result=Workspace:Raycast(Vector3.new(x,maxY+0xc8,z),
                        Vector3.new(0x0,-math.max(0x320,maxY-minY+0x190),0x0),rayParams)
                    local groundY=result and result.Position.Y or minY
                    local base=Vector3.new(x,groundY+0x3,z)
                    local mount=partyPart("\083\107\121\076\097\115\101\114\069\109\105\116\116\101\114",Vector3.new(.6,.6,.6),
                        CFrame.new(base),palette[i%#palette+0x1])
