                local length = longX and sz.X or sz.Z
                local width = longX and sz.Z or sz.X
                local y = sz.Y / 0x2 + .055
                local function laneAlongX()
                    local edge = math.max(1.2, sz.Z / 0x2 - 1.25)
                    for _,side in ipairs({-0x1,0x1}) do
                        makeNeon(part,"\084\111\107\121\111\076\097\110\101\069\100\103\101",Vector3.new(sz.X,.055,.2),CFrame.new(0x0,y,side*edge),side==0x1 and cyan or pink,.22)
                    end
                    local dashCount = math.min(0x50,math.max(0x1,math.floor(sz.X/0xd)))
                    for i=0x1,dashCount do
                        local t=-sz.X/0x2+(i-.5)*sz.X/dashCount
                        makeNeon(part,"\084\111\107\121\111\067\101\110\116\101\114\068\097\115\104",Vector3.new(math.min(0x5,sz.X/dashCount*.55),.06,.25),CFrame.new(t,y,0x0),amber,.23)
                    end
                end
                local function laneAlongZ()
                    local edge = math.max(1.2, sz.X / 0x2 - 1.25)
                    for _,side in ipairs({-0x1,0x1}) do
                        makeNeon(part,"\084\111\107\121\111\076\097\110\101\069\100\103\101",Vector3.new(.2,.055,sz.Z),CFrame.new(side*edge,y,0x0),side==0x1 and cyan or pink,.22)
                    end
                    local dashCount = math.min(0x50,math.max(0x1,math.floor(sz.Z/0xd)))
                    for i=0x1,dashCount do
                        local t=-sz.Z/0x2+(i-.5)*sz.Z/dashCount
                        makeNeon(part,"\084\111\107\121\111\067\101\110\116\101\114\068\097\115\104",Vector3.new(.25,.06,math.min(0x5,sz.Z/dashCount*.55)),CFrame.new(0x0,y,t),amber,.23)
                    end
                end
                if roads < MAX_ROADS and length >= 0x24 then
                    roads += 0x1
                    if length / math.max(width,0x1) >= 1.65 then
                        if longX then laneAlongX() else laneAlongZ() end
