        local saved = {}
        originals[tool] = saved
        for _, part in ipairs(tool:GetDescendants()) do
            if part:IsA("\066\097\115\101\080\097\114\116") and not part:IsDescendantOf(visual) then
                saved[part] = part.LocalTransparencyModifier
                part.LocalTransparencyModifier = 0x1
            end
        end
        tool.Destroying:Connect(function() originals[tool] = nil end)
    end
    local function checkContainer(container)
        if not container then return end
        for _, child in ipairs(container:GetChildren()) do
            if child:IsA("\084\111\111\108") then task.defer(applyVisual, child) end
        end
        container.ChildAdded:Connect(function(child)
            if child:IsA("\084\111\111\108") then task.defer(applyVisual, child) end
        end)
    end
    local function restoreVisual(tool)
        local visual = tool:FindFirstChild("\121\048\117\110\103\068\097\114\101\082\101\112\108\097\099\101\109\101\110\116\065\112\112\101\097\114\097\110\099\101")
        if visual then visual:Destroy() end
        local saved = originals[tool]
        if saved then
            for part, transparency in pairs(saved) do
                if part and part.Parent then part.LocalTransparencyModifier = transparency end
            end
            originals[tool] = nil
        end
    end
    local function refreshAll()
        for _, container in ipairs({player:FindFirstChildOfClass("\066\097\099\107\112\097\099\107"), player.Character}) do
            if container then
                for _, tool in ipairs(container:GetChildren()) do
                    if tool:IsA("\084\111\111\108") and known[tool.Name] then
                        if settings.enabled then applyVisual(tool) else restoreVisual(tool) end
                    end
                end
            end
        end
    end
    checkContainer(player:WaitForChild("\066\097\099\107\112\097\099\107"))
    if player.Character then checkContainer(player.Character) end
    player.CharacterAdded:Connect(checkContainer)
     
    task.spawn(function()
        local previous = settings.enabled
        local previousAssetId = settings.assetId
        while task.wait(0.15) do
            if settings.enabled ~= previous or settings.assetId ~= previousAssetId then
                local assetChanged = settings.assetId ~= previousAssetId
                previous = settings.enabled
                previousAssetId = settings.assetId
                if assetChanged then
                    for _, container in ipairs({player:FindFirstChildOfClass("\066\097\099\107\112\097\099\107"), player.Character}) do
                        if container then
                            for _, tool in ipairs(container:GetChildren()) do
                                if tool:IsA("\084\111\111\108") and known[tool.Name] then restoreVisual(tool) end
                            end
                        end
                    end
                end
                refreshAll()
            end
        end
    end)
end

 
